Marco (SDK): Draft TS snippet (TS SDK >=3.2) without imports: 
```ts
// parse headers, retry up to 3 times
async function sendWithRetry(req){
  for(let i=0;i<3;i++){
    const res = await client.generate(req)
    if(res.status===429){
      const d = parseInt(res.headers['retry-after']||res.headers['x-rw-retry']||'1')
      await sleep(d*1000*Math.pow(2,i))
      continue
    }
    return res
  }
  throw new Error('rate limited')
}
```
